          {
            return -EOPNOTSUPP;
          }
        priv->auth_cipher = (uint32_t)iwr->u.param.value;
        return OK;

      default:
        return -EOPNOTSUPP;
    }
#else
  (void)lower;
  (void)iwr;
  (void)set;
  return -ENOSYS;
#endif
}

